cat > src/App.css <<'EOF'
* { box-sizing: border-box; }
body { margin: 0; }
.app { min-height: 100vh; background: var(--g-color-base-generic-ultralight); color: var(--g-color-text-primary); }
.topbar { background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic); }
.topbar-inner { max-width: 1320px; height: 80px; padding: 0 var(--g-spacing-8); margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); }
.identity, .header-actions, .period-controls, .report-label, .stat-label, .stat-value, .chart-controls, .legend, .hint, .theme-indicator { display: flex; align-items: center; gap: var(--g-spacing-3); }
.identity, .header-actions { flex-shrink: 0; }
.brand-mark { display: flex; align-items: center; gap: 3px; height: 30px; width: 30px; transform: rotate(12deg); }
.brand-mark i { width: 5px; height: 13px; border-radius: var(--g-border-radius-s); background: var(--g-color-text-utility); }
.brand-mark i:nth-child(2) { height: 27px; }
.brand-mark i:nth-child(3) { height: 20px; }
.brand-mark i:nth-child(4) { height: 10px; }
.wordmark { font-size: 29px; font-weight: 750; letter-spacing: -1.3px; }
.brand-dot { color: var(--g-color-text-utility); }
.header-divider { height: 22px; width: 1px; background: var(--g-color-line-generic); margin: 0 var(--g-spacing-3); }
.theme-label { font-size: 12px; color: var(--g-color-text-secondary); }
.theme-buttons { display: flex; padding: var(--g-spacing-1); border-radius: var(--g-border-radius-l); background: var(--g-color-base-generic); }
