    catch { return 'light'; }
  });
  const toggleTheme = () => {
    const next = theme === 'light' ? 'dark' : 'light';
    setTheme(next);
    try { localStorage.setItem('pulse-theme', next); } catch { /* Theme still works when storage is unavailable. */ }
  };
  return <ThemeProvider theme={theme}><App onThemeChange={toggleTheme}/></ThemeProvider>;
}

