.stat-card { background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); padding: var(--g-spacing-5) var(--g-spacing-6); }
.stat-icon { display: grid; place-items: center; width: 28px; height: 28px; font-size: 20px; border-radius: var(--g-border-radius-m); background: var(--g-color-base-utility-light); }
.utility { color: var(--g-color-text-utility); }
.positive { color: var(--g-color-text-positive); }
.stat-icon.positive { background: var(--g-color-base-positive-light); }
.stat-icon.neutral { background: var(--g-color-base-generic); color: var(--g-color-text-secondary); }
.stat-value { margin: var(--g-spacing-4) 0 var(--g-spacing-2); gap: var(--g-spacing-3); flex-wrap: wrap; }
.stat-value > span:first-child { letter-spacing: -1px; font-variant-numeric: tabular-nums; }
.stat-change { color: var(--g-color-text-positive); background: var(--g-color-base-positive-light); border-radius: var(--g-border-radius-s); padding: var(--g-spacing-1) var(--g-spacing-2); font-size: 11px; }
.chart-card { background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-xl); overflow: hidden; box-shadow: 0 4px 16px -12px var(--g-color-sfx-shadow); }
.chart-heading { display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-4); padding: var(--g-spacing-6) var(--g-spacing-7) 0; }
.chart-heading h2, .bottom-panels h3 { margin: 0; }
.chart-heading p { margin: var(--g-spacing-2) 0 0; }
.chart-controls { gap: var(--g-spacing-2); }
.chart-meta { display: flex; justify-content: space-between; align-items: center; gap: var(--g-spacing-3); padding: var(--g-spacing-6) var(--g-spacing-7) var(--g-spacing-2); }
.legend { gap: var(--g-spacing-4); flex-wrap: wrap; }
.legend-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: currentColor; margin-right: var(--g-spacing-2); }
.legend-button { --g-button-text-color: var(--g-color-text-secondary); }
.is-hidden { opacity: .4; text-decoration: line-through; }
.chart-plot { height: 325px; margin: var(--g-spacing-2) var(--g-spacing-6) var(--g-spacing-4); --gcharts-axis-tick-color: var(--g-color-line-generic); }
.chart-footer { border-top: 1px solid var(--g-color-line-generic); padding: var(--g-spacing-4) var(--g-spacing-7); display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); font-size: 11px; color: var(--g-color-text-secondary); }
.info-circle { border: 1px solid var(--g-color-text-hint); border-radius: 50%; width: 14px; height: 14px; display: inline-grid; place-items: center; font-size: 10px; flex-shrink: 0; }
.theme-indicator { white-space: nowrap; font-size: 11px; gap: var(--g-spacing-2); }
.bottom-panels { display: grid; grid-template-columns: 1fr 1fr; gap: var(--g-spacing-4); margin-top: var(--g-spacing-5); }
.insight, .display-settings { border-radius: var(--g-border-radius-l); padding: var(--g-spacing-5) var(--g-spacing-6); display: flex; align-items: flex-start; gap: var(--g-spacing-4); }
.insight { background: var(--g-color-base-utility-light); }
.insight-icon { width: 32px; height: 32px; display: grid; place-items: center; border-radius: var(--g-border-radius-m); color: var(--g-color-text-utility); background: var(--g-color-base-background); font-size: 22px; flex-shrink: 0; }
.bottom-panels p { margin: var(--g-spacing-2) 0 0; line-height: 1.65; }
.bottom-panels strong { color: var(--g-color-text-primary); font-weight: 500; }
.display-settings { border: 1px solid var(--g-color-line-generic); background: var(--g-color-base-background); justify-content: space-between; align-items: center; }
.switches { display: flex; flex-direction: column; gap: var(--g-spacing-3); flex-shrink: 0; }
.page-footer { display: flex; justify-content: space-between; gap: var(--g-spacing-4); margin-top: var(--g-spacing-8); color: var(--g-color-text-hint); font-size: 11px; }
.footer-brand { color: var(--g-color-text-secondary); font-weight: 700; font-size: 14px; margin-right: var(--g-spacing-2); }
.empty-state { height: 100%; display: flex; align-items: center; justify-content: center; flex-direction: column; gap: var(--g-spacing-4); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
@media (min-width: 1400px) { .main { padding-top: var(--g-spacing-8); } .chart-plot { height: 365px; } }
@media (max-width: 1000px) { .date-range { display: none; } .stat-card { padding: var(--g-spacing-4); } .stat-value { gap: var(--g-spacing-2); } .display-settings { align-items: flex-start; flex-direction: column; } .switches { flex-direction: row; flex-wrap: wrap; } }
@media (max-width: 700px) {
  .topbar-inner { height: 66px; padding: 0 var(--g-spacing-4); }
  .identity > .header-divider, .identity > .g-text, .theme-label, .header-actions > .header-divider, .avatar { display: none; }
  .main { padding: var(--g-spacing-5) var(--g-spacing-4); }
  .breadcrumbs { margin-bottom: var(--g-spacing-6); }
  .page-heading { align-items: flex-start; flex-direction: column; margin-bottom: var(--g-spacing-6); }
  .page-toolbar { align-items: flex-start; flex-direction: column; }
  .stats { grid-template-columns: 1fr; gap: var(--g-spacing-3); }
  .stat-card { padding: var(--g-spacing-4) var(--g-spacing-5); }
  .stat-value { margin-top: var(--g-spacing-3); }
  .chart-heading { align-items: flex-start; flex-direction: column; padding: var(--g-spacing-5); }
  .chart-meta { align-items: flex-start; flex-direction: column; padding: 0 var(--g-spacing-4) var(--g-spacing-3); }
  .legend { gap: var(--g-spacing-1); }
  .chart-plot { height: 280px; margin: var(--g-spacing-2); }
  .chart-footer { align-items: flex-start; padding: var(--g-spacing-4); }
  .hint { align-items: flex-start; gap: var(--g-spacing-2); }
  .bottom-panels { grid-template-columns: 1fr; }
  .page-footer { flex-direction: column; gap: var(--g-spacing-2); }
}
EOF
cat > src/main.tsx <<'EOF'
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React, {useState} from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider, configure} from '@gravity-ui/uikit';
import {App} from './App';

configure({lang: 'ru'});

function Root() {
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    try { return localStorage.getItem('pulse-theme') === 'dark' ? 'dark' : 'light'; }
    catch { return 'light'; }
  });
  const toggleTheme = () => {
    const next = theme === 'light' ? 'dark' : 'light';
    setTheme(next);
    try { localStorage.setItem('pulse-theme', next); } catch { /* Theme still works when storage is unavailable. */ }
  };
  return <ThemeProvider theme={theme}><App onThemeChange={toggleTheme}/></ThemeProvider>;
}

ReactDOM.createRoot(document.getElementById('root')"'!).render(<React.StrictMode><Root/></React.StrictMode>);
EOF
npm run build'

